    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Executive Apartments da Rennert em Nova York, pensados para quem quer um verdadeiro lar temporário na cidade: apartamentos e estúdios que permitem cozinhar as próprias refeições, manter os horários de trabalho e explorar a cidade no próprio ritmo. São especialmente populares entre profissionais que combinam negócios com as aulas de inglês. As configurações incluem estúdio individual, estúdio duplo, quarto individual em apartamento compartilhado e guest rooms em Manhattan. Todos os estudantes precisam ter no mínimo 18 anos e assinar um regulamento antes da chegada, e é cobrada uma taxa de colocação de acomodação na reserva. Nesta opção o quarto é duplo/twin (para quem viaja acompanhado ou dividido com outro estudante do mesmo gênero) e o banheiro é compartilhado. As refeições não estão inclusas: o regime é self-catering, com liberdade para cozinhar e montar a própria rotina alimentar. Estúdio para duas pessoas, ideal para quem viaja acompanhado.</p><p>Suplementos e condições: Noite extra: USD 85; Depósito caução (reembolsável): USD 500; Outro suplemento: USD 100.</p><p>Lista oficial Rennert 2026 Fees &amp; Dates. Preços por semana e por pessoa. Chegada no domingo e saída no sábado. Idade mínima de 17 anos para residência e apart-hotel e 18 anos para apartamentos. Pode haver sobretaxa semanal em períodos de feriado, sem valor publicado. Troca de quarto US$100. Taxa de colocação de acomodacao US$125, não reembolsável. Apartamentos exigem caução reembolsável de US$500 paga na escola na chegada; no máximo 2 noites extras, 3 ou mais sao cobradas como semana inteira. Double room studio apartment US$450 por pessoa.</p>','["Estúdio ou Quarto em Apartamento", "Cozinha Própria", "Self-catering", "Somente 18+", "Opções em Manhattan", "Privacidade", "Indicado para Executivos", "Regulamento Assinado na Reserva", "Taxa de Colocação", "Quarto Duplo/Twin", "Banheiro Compartilhado", "Estúdio Duplo", "Ideal para executivos e profissionais que combinam trabalho e curso", "Ideal para quem quer cozinhar e ter total liberdade de horários", "Ideal para quem prefere privacidade a serviços inclusos", "Ideal para quem fica mais tempo em Nova York", "Ideal para quem viaja acompanhado ou quer dividir custos", "Ideal para quem gosta de socializar e não se importa em dividir espaços", "Ideal para quem quer autonomia para cozinhar e controlar o orçamento"]'::jsonb,'["Menos indicado para menores de 18 anos", "Menos indicado para quem quer refeições inclusas", "Menos indicado para quem procura a opção mais econômica", "Menos indicado para quem quer o convívio de uma família ou residência estudantil", "Menos indicado para quem precisa de privacidade e silêncio", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem não quer cozinhar nem se preocupar com compras de supermercado"]'::jsonb);
