    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Executive Apartments da Rennert em Nova York, pensados para quem quer um verdadeiro lar temporário na cidade: apartamentos e estúdios que permitem cozinhar as próprias refeições, manter os horários de trabalho e explorar a cidade no próprio ritmo. São especialmente populares entre profissionais que combinam negócios com as aulas de inglês. As configurações incluem estúdio individual, estúdio duplo, quarto individual em apartamento compartilhado e guest rooms em Manhattan. Todos os estudantes precisam ter no mínimo 18 anos e assinar um regulamento antes da chegada, e é cobrada uma taxa de colocação de acomodação na reserva. Nesta opção você fica em quarto individual com banheiro privativo, de uso exclusivo. As refeições não estão inclusas: o regime é self-catering, com liberdade para cozinhar e montar a própria rotina alimentar.</p><p>Suplementos e condições: Noite extra: USD 95; Depósito caução (reembolsável): USD 500; Outro suplemento: USD 100.</p><p>Lista oficial Rennert 2026 Fees &amp; Dates (rennert-2026-fees-dates.pdf). Preços por semana e por pessoa. Chegada no domingo e saída no sábado. Idade mínima de 17 anos para residência, hostel e apart-hotel; 18 anos para apartamentos. A escola informa que pode haver sobretaxa semanal em períodos de feriado, sem valor publicado. Noite extra: US$95 (quarto individual) ou US$85 (quarto duplo); no máximo 2 noites extras em apartamento, 3 ou mais sao cobradas como semana inteira. Troca de quarto: US$100. Taxa de colocação de acomodacao de US$125, não reembolsável. Apartamentos exigem caução reembolsável de US$500 paga na chegada. Este quarto corresponde a Studio single room apartment, apartamento estúdio individual com banheiro privativo.</p>','["Estúdio ou Quarto em Apartamento", "Cozinha Própria", "Self-catering", "Somente 18+", "Opções em Manhattan", "Privacidade", "Indicado para Executivos", "Regulamento Assinado na Reserva", "Taxa de Colocação", "Quarto Individual", "Banheiro Privativo", "Ideal para executivos e profissionais que combinam trabalho e curso", "Ideal para quem quer cozinhar e ter total liberdade de horários", "Ideal para quem prefere privacidade a serviços inclusos", "Ideal para quem fica mais tempo em Nova York", "Ideal para quem valoriza privacidade total e silêncio para estudar", "Ideal para quem prefere não dividir banheiro com ninguém", "Ideal para quem quer autonomia para cozinhar e controlar o orçamento"]'::jsonb,'["Menos indicado para menores de 18 anos", "Menos indicado para quem quer refeições inclusas", "Menos indicado para quem procura a opção mais econômica", "Menos indicado para quem quer o convívio de uma família ou residência estudantil", "Menos indicado para quem procura a alternativa mais barata", "Menos indicado para quem quer dividir o quarto com um amigo para reduzir custos", "Menos indicado para quem não quer cozinhar nem se preocupar com compras de supermercado"]'::jsonb);
