    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Executive Apartments da Rennert em Nova York, pensados para quem quer um verdadeiro lar temporário na cidade: apartamentos e estúdios que permitem cozinhar as próprias refeições, manter os horários de trabalho e explorar a cidade no próprio ritmo. São especialmente populares entre profissionais que combinam negócios com as aulas de inglês. As configurações incluem estúdio individual, estúdio duplo, quarto individual em apartamento compartilhado e guest rooms em Manhattan. Todos os estudantes precisam ter no mínimo 18 anos e assinar um regulamento antes da chegada, e é cobrada uma taxa de colocação de acomodação na reserva. Nesta opção você fica em quarto individual, com banheiro compartilhado com os demais moradores. As refeições não estão inclusas: o regime é self-catering, com liberdade para cozinhar e montar a própria rotina alimentar. Quarto individual dentro de um apartamento compartilhado.</p><p>Suplementos e condições: Noite extra: USD 95; Depósito caução (reembolsável): USD 500; Outro suplemento: USD 100.</p><p>Lista oficial Rennert 2026 Fees &amp; Dates. Preços por semana e por pessoa. Chegada no domingo e saída no sábado. Idade mínima de 17 anos para residência e apart-hotel e 18 anos para apartamentos. Pode haver sobretaxa semanal em períodos de feriado, sem valor publicado. Troca de quarto US$100. Taxa de colocação de acomodacao US$125, não reembolsável. Apartamentos exigem caução reembolsável de US$500 paga na escola na chegada; no máximo 2 noites extras, 3 ou mais sao cobradas como semana inteira. Single room shared apartment: a tabela publica a faixa de US$550 a US$750 por semana; registrado o valor inicial de US$550. Confirmar o valor exato conforme o apartamento.</p>','["Estúdio ou Quarto em Apartamento", "Cozinha Própria", "Self-catering", "Somente 18+", "Opções em Manhattan", "Privacidade", "Indicado para Executivos", "Regulamento Assinado na Reserva", "Taxa de Colocação", "Quarto Individual", "Banheiro Compartilhado", "Quarto em Apartamento Compartilhado", "Ideal para executivos e profissionais que combinam trabalho e curso", "Ideal para quem quer cozinhar e ter total liberdade de horários", "Ideal para quem prefere privacidade a serviços inclusos", "Ideal para quem fica mais tempo em Nova York", "Ideal para quem quer privacidade no quarto pagando menos que uma suíte", "Ideal para quem não se incomoda em dividir o banheiro", "Ideal para quem quer autonomia para cozinhar e controlar o orçamento"]'::jsonb,'["Menos indicado para menores de 18 anos", "Menos indicado para quem quer refeições inclusas", "Menos indicado para quem procura a opção mais econômica", "Menos indicado para quem quer o convívio de uma família ou residência estudantil", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem tem horários muito rígidos de banho e rotina", "Menos indicado para quem não quer cozinhar nem se preocupar com compras de supermercado"]'::jsonb);
